import{_ as s,l as i,o as a,c as n,v as r,p as l,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"侦听与目录","description":"","frontmatter":{"title":"侦听与目录","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/snoop-vs-directory.md","filePath":"cs/snoop-vs-directory.md","lastUpdated":1789023840000}'),E={name:"cs/snoop-vs-directory.md"};function h(A,e,m,_,u,S){const o=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="侦听与目录" tabindex="-1">侦听与目录 <a class="header-anchor" href="#侦听与目录" aria-label="Permalink to &quot;侦听与目录&quot;">​</a></h1><div class="epigraph"><p>MESI 的状态机还要靠一种传播手段：每人听总线上所有事务，或向目录打听谁持有副本。</p><footer>—— 据 Censier and Feautrier, A New Solution to Coherence Problems in Multicache Systems, IEEE TC 1978；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/mesi-protocol">上一课</a>钉了 M/E/S/I 转换，并假定「每核看见总线上的读/写」。核数上升时广播先垮。<a href="/cs/multicore-shared-cache">多核与共享缓存</a>已把互连画成抽象。本课不重画四态。缺口是传播：窥探（snoop）对广播介质，目录把「谁有这行」记在主节点。本课只对照这两种，不写目录项的全部编码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>窥探：每条 miss/upgrade 出现在共享总线或广播网上，所有 cache 控制器比较自己的标签并作答（提供数据、作废、降级）。正确性靠「人人看见同一全序事务」。缺口是带宽与监听过滤随核数线性涨——包含性 L3 只能过滤一部分。</p><p>目录：每行有一个家节点，存位向量或链表：哪些核可能有副本。请求先到家，家只向有副本的核发点对点消息。无广播，但多一跳延迟，且目录本身要存储。</p><p><span class="marginnote">Censier–Feautrier 1978 给出目录方案的早期完整表述。总线窥探与 Illinois MESI 同一时代，对象是小规模对称多处理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>窥探实现：总线仲裁给出全局序；写升级等待所有 snoop 响应。监听过滤器、包含 LLC 用来减少 L1 被问的次数。</p><p>目录实现：数据请求 → 目录；若行在 M，转发到持有者，持有者写回或直接给请求者，目录更新位向量。替换通知目录（或用超时/静默替换加后续探测）。</p>',10)),(a(),l(c,null,{default:t(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E6%9F%90%E6%A0%B8%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20BUS%5B%22%E7%AA%A5%E6%8E%A2%EF%BC%9A%E5%B9%BF%E6%92%AD%E7%BB%99%E6%89%80%E6%9C%89%E4%BA%BA%22%5D%0A%20%20MISS%20--%3E%20DIR%5B%22%E7%9B%AE%E5%BD%95%EF%BC%9A%E9%97%AE%E5%AE%B6%E8%8A%82%E7%82%B9%22%5D%0A%20%20DIR%20--%3E%20P2P%5B%22%E5%8F%AA%E9%80%9A%E7%9F%A5%E6%8C%81%E6%9C%89%E8%80%85%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>两种都实现同一套 MESI 不变式；变的是消息条数与延迟分档。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>窥探的「最近写」由总线序定义。目录的「最近写」由家节点序列化到该行的请求定义——同一行仍有全序，不同行之间的序是存储模型的事，下一课。</p><p>NUMA：目录切片跟内存走，远程行必经互连。窥探很难跨太多芯片。包含层次与目录可叠加：LLC 当本节点过滤器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MOESI 的 Owned 作为传播优化（脏共享不写回内存），不把具体互联协议当正文。也不把目录当成操作系统页表：粒度是 cache 行，由硬件维护。存储一致性模型（SC/TSO）下一课才问多地址交错。</p><p>后课默认：小规模用窥探，大规模用目录；MESI 状态仍适用。程序员问「两条 store 他核怎么看见」，要另加模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>窥探靠广播与人人监听；目录靠家节点与点对点。</li><li>不变式仍是 MESI；变的是可扩展性与延迟。</li><li>多地址上的可见顺序是下一课存储模型。</li><li>出处：Censier and Feautrier, <em>IEEE TC</em>, 1978；Papamarcos and Patel, <em>ISCA</em>, 1984；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const f=s(E,[["render",h]]);export{C as __pageData,f as default};
